import gurobipy as gp
from gurobipy import GRB
suppliers = ['S1', 'S2', 'S3', 'S4', 'S5', 'S6', 'S7', 'S8', 'S9', 'S10', 'S11', 'S12']
customers = ['C1', 'C2', 'C3', 'C4', 'C5', 'C6', 'C7', 'C8', 'C9', 'C10', 'C11', 'C12']
demand = {'C1': 52, 'C2': 80, 'C3': 392, 'C4': 103, 'C5': 32, 'C6': 1426, 'C7': 1024, 'C8': 2736, 'C9': 1129, 'C10': 676, 'C11': 2631, 'C12': 31}
supply_capacity = {'S1': 58, 'S2': 32, 'S3': 6161, 'S4': 4, 'S5': 47, 'S6': 178, 'S7': 142, 'S8': 164, 'S9': 1011, 'S10': 6, 'S11': 7081, 'S12': 948}
cost = {'S1': {'C1': 134.7288244, 'C2': 72.30045141, 'C3': 37.97599274, 'C4': 611.846565, 'C5': 1650.33539, 'C6': 32.97044487, 'C7': 34.99837373, 'C8': 73.2520737, 'C9': 165.7520898, 'C10': 82.52035828, 'C11': 1538.830198, 'C12': 2320.114648}, 'S2': {'C1': 23.83536919, 'C2': 1128.633287, 'C3': 187.0545959, 'C4': 1.607733713, 'C5': 2227.703699, 'C6': 72.44693149, 'C7': 12.60074797, 'C8': 1078.772955, 'C9': 383.7220569, 'C10': 82.81152504, 'C11': 1702.172476, 'C12': 1925.844697}, 'S3': {'C1': 1138.49876, 'C2': 231.8983422, 'C3': 44.15682267, 'C4': 962.5481641, 'C5': 980.1306032, 'C6': 1107.515751, 'C7': 741.7073424, 'C8': 136.702044, 'C9': 1182.516112, 'C10': 664.1846793, 'C11': 36.70238978, 'C12': 1405.050692}, 'S4': {'C1': 1043.75628, 'C2': 24.20701606, 'C3': 1120.989044, 'C4': 1027.543764, 'C5': 893.4457578, 'C6': 1244.262678, 'C7': 980.0297708, 'C8': 513.5650272, 'C9': 977.6321548, 'C10': 642.5520451, 'C11': 437.9556823, 'C12': 76.12498669}, 'S5': {'C1': 4.939930662, 'C2': 1278.181574, 'C3': 549.7570743, 'C4': 21.33547411, 'C5': 98.3268928, 'C6': 452.0903463, 'C7': 595.5981934, 'C8': 70.84029747, 'C9': 0.001236242, 'C10': 1783.086568, 'C11': 1619.615466, 'C12': 116.0849791}, 'S6': {'C1': 2105.53986, 'C2': 1340.977056, 'C3': 2077.274728, 'C4': 2202.25154, 'C5': 20.53369588, 'C6': 2514.09836, 'C7': 2393.213467, 'C8': 1197.765543, 'C9': 102.3244025, 'C10': 788.4640306, 'C11': 818.953226, 'C12': 17.24964579}, 'S7': {'C1': 61.36183063, 'C2': 113.2371696, 'C3': 50.23107648, 'C4': 1219.195108, 'C5': 869.8689864, 'C6': 58.3717723, 'C7': 957.3213131, 'C8': 168.9964798, 'C9': 1363.342714, 'C10': 519.3858364, 'C11': 483.3345987, 'C12': 1412.765288}, 'S8': {'C1': 1169.364099, 'C2': 1037.217074, 'C3': 732.3577707, 'C4': 865.2255769, 'C5': 1510.029619, 'C6': 780.8537898, 'C7': 860.7971696, 'C8': 935.9126433, 'C9': 61.8250491, 'C10': 72.78392607, 'C11': 1479.11372, 'C12': 65.87463475}, 'S9': {'C1': 7.936521667, 'C2': 1357.538761, 'C3': 628.3001825, 'C4': 25.24514182, 'C5': 1760.008525, 'C6': 604.6583536, 'C7': 696.6774833, 'C8': 1586.409318, 'C9': 89.68006943, 'C10': 1580.726256, 'C11': 1423.561541, 'C12': 2000.5638}, 'S10': {'C1': 1685.340976, 'C2': 437.3938491, 'C3': 1568.893994, 'C4': 1486.926897, 'C5': 498.3754447, 'C6': 1493.386021, 'C7': 70.17952879, 'C8': 526.9999923, 'C9': 1527.66066, 'C10': 2.676413574, 'C11': 202.7267124, 'C12': 45.95308313}, 'S11': {'C1': 937.1094078, 'C2': 903.0141416, 'C3': 264.7208999, 'C4': 21.82334018, 'C5': 1661.105486, 'C6': 18.59349094, 'C7': 372.0817876, 'C8': 956.6955599, 'C9': 42.91201853, 'C10': 1274.322753, 'C11': 1574.79615, 'C12': 1826.428257}, 'S12': {'C1': 1685.757685, 'C2': 377.3256673, 'C3': 1347.016273, 'C4': 1737.020031, 'C5': 23.61217798, 'C6': 83.08521829, 'C7': 1476.125824, 'C8': 530.0021927, 'C9': 1782.844263, 'C10': 0.010486218, 'C11': 11.16932045, 'C12': 963.9941815}}
for i in suppliers:
    if i not in cost:
        raise ValueError(f'Missing cost row for supplier {i}')
    for j in customers:
        if j not in cost[i]:
            raise ValueError(f'Missing cost entry for supplier {i}, customer {j}')
for j in customers:
    if j not in demand:
        raise ValueError(f'Missing demand for customer {j}')
for i in suppliers:
    if i not in supply_capacity:
        raise ValueError(f'Missing supply capacity for supplier {i}')
m = gp.Model('Retail_Supply_Chain_Optimization')
x_vars = m.addVars(suppliers, customers, lb=0, vtype=GRB.CONTINUOUS, name='')
m.setObjective(gp.quicksum((cost[i][j] * x_vars[i, j] for i in suppliers for j in customers)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x_vars[i, j] for i in suppliers)) >= demand[j] for j in customers), name='')
m.addConstrs((gp.quicksum((x_vars[i, j] for j in customers)) <= supply_capacity[i] for i in suppliers), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')